  /// All available built-in VS Code themes.
  static final List<VsCodeTheme> all = [
    flexokiDark,
    flexokiLight,
    kanagawaDragon,
    kanagawaLotus,
    kanagawaWave,
    tokenDark,
    tokenFlintDark,
    tokenFlintLight,
    tokenLight,
    tokenMeridianDark,
    tokenMeridianLight,
    tokenTemperDark,
    tokenTemperLight,
    tokenUltraDark,
    tokenUltraLight,
  ];

  /// Resolves a theme by name or filename.
  static VsCodeTheme? findByName(String name) {
    final lower = name.toLowerCase().trim();
    for (final t in all) {
      if (t.name?.toLowerCase() == lower) return t;
    }
    return null;
  }
}
